/// One frame of the capture-chain analyser.
///
/// Band levels are dBFS, floored, one entry per band, and the three traces are
/// always the same length as `centres_hz`.
class UiSpectrum {
  /// Centre frequency of each band. Sent every frame rather than fetched
  /// once, so the axis and the data can never disagree about how many bands
  /// there are.
  final Float32List centresHz;

  /// The microphone, before any processing.
  final Float32List rawDb;

  /// What the noise gate was about to judge.
  final Float32List preGateDb;

  /// What reached the encoder. Drawn whether or not it was transmitted;
  /// `transmitting` is what says which.
  final Float32List sentDb;

  /// Quietest level in the data, for scaling the axis.
  final double floorDb;

  /// How tonal the pre-gate signal is, 0..1.
  final double harmonicity;

  /// Whether the block this frame describes actually went out.
  final bool transmitting;

  /// Frame counter. If this stops moving the worker has stopped, which on
  /// screen is indistinguishable from silence unless the reader checks.
  final BigInt seq;

  const UiSpectrum({
    required this.centresHz,
    required this.rawDb,
    required this.preGateDb,
    required this.sentDb,
    required this.floorDb,
    required this.harmonicity,
    required this.transmitting,
    required this.seq,
  });

  @override
  int get hashCode =>
      centresHz.hashCode ^
      rawDb.hashCode ^
      preGateDb.hashCode ^
      sentDb.hashCode ^
      floorDb.hashCode ^
      harmonicity.hashCode ^
      transmitting.hashCode ^
      seq.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiSpectrum &&
          runtimeType == other.runtimeType &&
          centresHz == other.centresHz &&
          rawDb == other.rawDb &&
          preGateDb == other.preGateDb &&
          sentDb == other.sentDb &&
          floorDb == other.floorDb &&
          harmonicity == other.harmonicity &&
          transmitting == other.transmitting &&
          seq == other.seq;
}

/// One stage of the capture chain.
///
/// Carries no prose. The panel is fully localised, and a message composed in
/// Rust would be the one string in it that no translator can reach — so Dart
/// builds the label from `id`, `state` and `value`.
class UiStage {
  /// Stable identifier: `aec`, `rnnoise`, `gate`, `vad`, `harmonicity`,
  /// `agc`, `dehiss`, `feedback`, `profile`, `transmit`.
  final String id;
  final StageState state;

  /// The one number that stage is about, in whatever unit suits it — dB for
  /// the AEC and the AGC, 0..1 for harmonicity, unused elsewhere.
  final double value;

  const UiStage({required this.id, required this.state, required this.value});

  @override
  int get hashCode => id.hashCode ^ state.hashCode ^ value.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiStage &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          state == other.state &&
          value == other.value;
}

class UiStageCost {
  /// Stable identifier, for the panel to localise. Never shown raw.
  final String id;
  final double meanUs;
  final int worstUs;

  const UiStageCost({
    required this.id,
    required this.meanUs,
    required this.worstUs,
  });

  @override
  int get hashCode => id.hashCode ^ meanUs.hashCode ^ worstUs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiStageCost &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          meanUs == other.meanUs &&
          worstUs == other.worstUs;
}

/// What one capture block costs, stage by stage, in microseconds.
///
/// **The measurement that says whether a slow stage is slow.** These are wall
/// clock, so a stage that the operating system descheduled mid-block is charged
/// for the wait — which on a four-core phone running a UI, an audio callback
/// and this worker is a large effect. [`Self::unattributed_us`] is what
/// separates the two: it is the part of the block that no stage was holding a
/// stopwatch on, so a big number there means the worker is being interrupted
/// rather than running slowly, and making a stage cheaper will not help.
///
/// This is why the enhancer's own guard was misleading. It measured only
/// itself, saw frames over 10 ms, and concluded the model could not keep up —
/// when the same model measured alone on the same phone comes in at 6.2 ms.
class UiStageCosts {
  /// One entry per stage, in the order the chain runs them.
  final List<UiStageCost> stages;

  /// The whole iteration, mean and worst, in microseconds.
  final double blockMeanUs;
  final int blockWorstUs;

  /// The part of the block no stage accounted for: scheduling, mostly.
  final double unattributedUs;

  /// Captured audio waiting for the worker when a block started, in ms.
  ///
  /// The consequence rather than a cost. A backlog that climbs is a chain
  /// that cannot keep up, and it says so before a sample is dropped.
  final double backlogMeanMs;
  final double backlogWorstMs;

  /// How many blocks these are averaged over. Zero means nothing has run.
  final BigInt blocks;

  /// The block budget, so the panel does not have to know it.
  final int budgetUs;

  const UiStageCosts({
    required this.stages,
    required this.blockMeanUs,
    required this.blockWorstUs,
    required this.unattributedUs,
    required this.backlogMeanMs,
    required this.backlogWorstMs,
    required this.blocks,
    required this.budgetUs,
  });

  @override
  int get hashCode =>
      stages.hashCode ^
      blockMeanUs.hashCode ^
      blockWorstUs.hashCode ^
      unattributedUs.hashCode ^
      backlogMeanMs.hashCode ^
      backlogWorstMs.hashCode ^
      blocks.hashCode ^
      budgetUs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiStageCosts &&
          runtimeType == other.runtimeType &&
          stages == other.stages &&
          blockMeanUs == other.blockMeanUs &&
          blockWorstUs == other.blockWorstUs &&
          unattributedUs == other.unattributedUs &&
          backlogMeanMs == other.backlogMeanMs &&
          backlogWorstMs == other.backlogWorstMs &&
          blocks == other.blocks &&
          budgetUs == other.budgetUs;
}

class UiStats {
  final String serverId;
  final double tcpPingMs;
  final double udpPingMs;

  /// "udp" for the low-latency path, "tcp" when tunnelling.
  final String transport;

  const UiStats({
    required this.serverId,
    required this.tcpPingMs,
    required this.udpPingMs,
    required this.transport,
  });

  @override
  int get hashCode =>
      serverId.hashCode ^
      tcpPingMs.hashCode ^
      udpPingMs.hashCode ^
      transport.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiStats &&
          runtimeType == other.runtimeType &&
          serverId == other.serverId &&
          tcpPingMs == other.tcpPingMs &&
          udpPingMs == other.udpPingMs &&
          transport == other.transport;
}

class UiUser {
  final int session;
  final String name;
  final int channelId;
  final bool talking;

  /// Muted server-side or by themselves — nobody hears them.
  final bool muted;
  final bool deafened;

  /// Silenced by us alone. Needs no permission and is invisible to others.
  final bool localMute;

  /// One word for the roster: talking, silent, muted, deafened, muted for you.
  final String status;

  const UiUser({
    required this.session,
    required this.name,
    required this.channelId,
    required this.talking,
    required this.muted,
    required this.deafened,
    required this.localMute,
    required this.status,
  });

  @override
  int get hashCode =>
      session.hashCode ^
      name.hashCode ^
      channelId.hashCode ^
      talking.hashCode ^
      muted.hashCode ^
      deafened.hashCode ^
      localMute.hashCode ^
      status.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiUser &&
          runtimeType == other.runtimeType &&
          session == other.session &&
          name == other.name &&
          channelId == other.channelId &&
          talking == other.talking &&
          muted == other.muted &&
          deafened == other.deafened &&
          localMute == other.localMute &&
          status == other.status;
}

/// A window of raw microphone audio for the background classifier.
class UiWaveform {
  /// 15 600 samples at 16 kHz — 0.975 s — which is the size YAMNet was built
  /// for. Crosses as a `Float32List`, so it is one 62 kB copy every few
  /// seconds rather than anything per block.
  final Float32List samples;

  /// Increments per window. Not moving means the worker stopped, which to a
  /// classifier is indistinguishable from a very quiet ride.
  final BigInt seq;

  const UiWaveform({required this.samples, required this.seq});

  @override
  int get hashCode => samples.hashCode ^ seq.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiWaveform &&
          runtimeType == other.runtimeType &&
          samples == other.samples &&
          seq == other.seq;
}
